        #pragma warning disable CS0618 // Type or member is obsolete
        public void Remove(
            ICellInternal obj,
            HashSet<FormKey> keys)
        {
            if (obj.Landscape != null && keys.Contains(obj.Landscape.FormKey))
            {
                obj.Landscape = null;
            }
            obj.NavigationMeshes.Remove(keys);
            obj.Persistent.Remove(keys);
            obj.Temporary.Remove(keys);
            obj.VisibleWhenDistant.Remove(keys);
        }
        
        public void Remove(
            ICellInternal obj,
            HashSet<FormKey> keys,
            Type type,
            bool throwIfUnknown)
        {
            switch (type.Name)
            {
                case "IMajorRecord":
                case "MajorRecord":
                case "IFallout3MajorRecord":
                case "Fallout3MajorRecord":
                case "IMajorRecordGetter":
                case "IFallout3MajorRecordGetter":
                    if (!Cell_Registration.SetterType.IsAssignableFrom(obj.GetType())) return;
                    this.Remove(obj, keys);
                    break;
                case "IPlaced":
                case "IPlacedGetter":
                    obj.Persistent.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.Temporary.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.VisibleWhenDistant.RemoveWhere(i => keys.Contains(i.FormKey));
                    break;
                case "Landscape":
                case "ILandscapeGetter":
                case "ILandscape":
                case "ILandscapeInternal":
                    {
                        if (obj.Landscape is {} Landscapeitem)
                        {
                            Landscapeitem.Remove(keys, type, throwIfUnknown);
                        }
                    }
                    break;
                case "NavigationMesh":
                case "INavigationMeshGetter":
                case "INavigationMesh":
                case "INavigationMeshInternal":
                    obj.NavigationMeshes.RemoveWhere(i => keys.Contains(i.FormKey));
                    break;
                case "PlacedBeam":
                case "IPlacedBeamGetter":
                case "IPlacedBeam":
                case "IPlacedBeamInternal":
                    obj.Persistent.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.Temporary.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.VisibleWhenDistant.RemoveWhere(i => keys.Contains(i.FormKey));
                    break;
                case "PlacedCreature":
                case "IPlacedCreatureGetter":
                case "IPlacedCreature":
                case "IPlacedCreatureInternal":
                    obj.Persistent.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.Temporary.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.VisibleWhenDistant.RemoveWhere(i => keys.Contains(i.FormKey));
                    break;
                case "PlacedGrenade":
                case "IPlacedGrenadeGetter":
                case "IPlacedGrenade":
                case "IPlacedGrenadeInternal":
                    obj.Persistent.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.Temporary.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.VisibleWhenDistant.RemoveWhere(i => keys.Contains(i.FormKey));
                    break;
                case "PlacedMissile":
                case "IPlacedMissileGetter":
                case "IPlacedMissile":
                case "IPlacedMissileInternal":
                    obj.Persistent.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.Temporary.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.VisibleWhenDistant.RemoveWhere(i => keys.Contains(i.FormKey));
                    break;
                case "PlacedNpc":
                case "IPlacedNpcGetter":
                case "IPlacedNpc":
                case "IPlacedNpcInternal":
                    obj.Persistent.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.Temporary.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.VisibleWhenDistant.RemoveWhere(i => keys.Contains(i.FormKey));
                    break;
                case "PlacedObject":
                case "IPlacedObjectGetter":
                case "IPlacedObject":
                case "IPlacedObjectInternal":
                    obj.Persistent.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.Temporary.RemoveWhere(i => keys.Contains(i.FormKey));
                    obj.VisibleWhenDistant.RemoveWhere(i => keys.Contains(i.FormKey));
                    break;
                default:
                    if (throwIfUnknown)
                    {
                        throw new ArgumentException($"Unknown major record type: {type}");
                    }
                    else
                    {
                        break;
                    }
            }
        }
        
